from __future__ import annotations

import datetime as dt
import hashlib
import json
import os
import queue
import random
import shutil
import subprocess
import tarfile
import tempfile
import threading
import time
from pathlib import Path
from typing import Any

from . import adapters

ROOT = Path(__file__).resolve().parents[2]
RESULTS = ROOT / "results"


def read_config(name: str) -> dict:
    return json.loads((ROOT / "config" / f"{name}.yaml").read_text())


def atomic_json(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_suffix(path.suffix + ".tmp")
    temp.write_text(json.dumps(value, indent=2, ensure_ascii=False) + "\n")
    temp.replace(path)


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def config_hashes() -> dict[str, str]:
    return {name: sha256(ROOT / "config" / f"{name}.yaml") for name in ("arms", "tasks", "run-policy", "rubric")}


def utc_now() -> str:
    return dt.datetime.now(dt.timezone.utc).isoformat()


def validate_cutoff(value: str) -> str:
    parsed = dt.datetime.fromisoformat(value)
    if parsed.tzinfo is None:
        raise ValueError("--cutoff must include a timezone offset")
    return parsed.isoformat()


def git(repo: Path, *args: str) -> str:
    result = subprocess.run(["git", "-C", str(repo), *args], text=True,
                            capture_output=True, timeout=30, check=True)
    return result.stdout.strip()


def validate_repos(repo_args: list[str]) -> dict[str, dict]:
    required = {name for task in read_config("tasks")["tasks"] for name in task["repos"]}
    repos: dict[str, dict] = {}
    for item in repo_args:
        if "=" not in item:
            raise ValueError("--repo requires name=/absolute/path")
        name, value = item.split("=", 1)
        if name not in required or not Path(value).is_absolute():
            raise ValueError(f"Invalid repository assignment: {item}")
        path = Path(value).resolve()
        if not path.is_dir():
            raise ValueError(f"Repository not found: {path}")
        commit = git(path, "rev-parse", "HEAD")
        if not commit or len(commit) != 40:
            raise ValueError(f"Could not pin commit for {path}")
        repos[name] = {"path": str(path), "commit": commit,
                       "working_tree_dirty": bool(git(path, "status", "--porcelain"))}
    return repos


def task_repo_names(task: dict, manifest: dict) -> list[str]:
    return task["repos"]


def pack_path(task_id: str) -> Path:
    return ROOT / "evidence" / task_id / "pack.json"


def pack_status(task_id: str, manifest: dict | None = None) -> tuple[bool, str]:
    path = pack_path(task_id)
    if not path.exists():
        return False, "judge evidence pack missing"
    try:
        pack = json.loads(path.read_text())
    except (OSError, json.JSONDecodeError):
        return False, "judge evidence pack is invalid JSON"
    if not isinstance(pack, dict):
        return False, "judge evidence pack must be an object"
    fields = ("reference_answer", "sources", "repo_facts", "ambiguities",
              "grading_guidance", "decision_changing_errors")
    if any(field not in pack for field in fields):
        return False, "judge evidence pack is incomplete"
    if "REPLACE" in json.dumps(pack) or not pack["reference_answer"] or not pack["sources"]:
        return False, "judge evidence pack contains placeholders or no sources"
    if not isinstance(pack["sources"], list) or any(
           not isinstance(source, dict) or
           not all(source.get(key) for key in ("title", "url", "retrieved_at", "snapshot_or_excerpt"))
           for source in pack["sources"]):
        return False, "judge evidence pack has an incomplete source"
    guidance = pack["grading_guidance"]
    if not isinstance(guidance, dict) or any(not isinstance(guidance.get(key), list) or
                                             not all(isinstance(item, str) and item for item in guidance[key])
                                             for key in ("must_check", "acceptable_alternatives", "do_not_penalize")):
        return False, "judge evidence pack has incomplete grading guidance"
    if manifest is not None:
        task = next(task for task in read_config("tasks")["tasks"] if task["id"] == task_id)
        selected = task_repo_names(task, manifest)
        if task["repos"] and not selected:
            return False, "task has no pinned repositories"
        facts = {item["repo"]: item["commit"] for item in pack["repo_facts"]}
        for name in selected:
            info = manifest["repos"].get(name)
            if info is None:
                return False, f"missing pinned repo {name}"
            if facts.get(name, facts.get(Path(info["path"]).name)) != info["commit"]:
                return False, f"judge evidence pack repo pin differs for {name}"
    return True, "ready"


def manifest_path(evaluation_id: str) -> Path:
    if not evaluation_id or any(c not in "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_" for c in evaluation_id):
        raise ValueError("Evaluation ID must contain only letters, digits, hyphens, underscores")
    return RESULTS / evaluation_id / "manifest.json"


def load_manifest(evaluation_id: str) -> dict:
    path = manifest_path(evaluation_id)
    if not path.exists():
        raise ValueError(f"No manifest for {evaluation_id}; run preflight first")
    value = json.loads(path.read_text())
    if value["config_hashes"] != config_hashes():
        raise ValueError("Config changed since preflight; use a new evaluation ID")
    return value


def _version(binary: str, env: dict[str, str] | None = None) -> str | None:
    if not shutil.which(binary, path=(env or os.environ).get("PATH")):
        return None
    try:
        proc = subprocess.run([binary, "--version"], text=True, capture_output=True,
                              timeout=10, env=env)
        return (proc.stdout or proc.stderr).strip().splitlines()[0][:200]
    except (OSError, subprocess.SubprocessError, IndexError):
        return None


def static_arm_check(arm: dict) -> dict:
    env = adapters.environment(arm, ROOT)
    binary = arm["binary"]
    version = _version(binary, env)
    if version is None:
        return {"status": "unavailable", "reason": f"{binary} not found in PATH", "version": None}
    details: dict[str, Any] = {"status": "needs_live_probe", "reason": None, "version": version,
                               "model": arm["model"], "reasoning": arm["reasoning"],
                               "search_provider": arm.get("search_provider"), "usage_fields": "unverified"}
    if arm["harness"] == "pi":
        try:
            output = subprocess.run([binary, "--list-models", arm["model"].split("/")[-1]],
                                    env=env, text=True, capture_output=True, timeout=15)
            if arm["model"].split("/")[-1] not in output.stdout:
                details.update(status="unavailable", reason="Pinned Pi model not listed")
            extensions = subprocess.run([binary, "list"], env=env, text=True,
                                        capture_output=True, timeout=15)
            details["extensions"] = extensions.stdout.strip().splitlines() if extensions.returncode == 0 else []
            if not all(package in extensions.stdout for package in ("pi-web-search", "pi-web-fetch")):
                details.update(status="unavailable", reason="Pi web search/fetch extensions are missing")
        except (OSError, subprocess.SubprocessError):
            details.update(status="unavailable", reason="Could not list Pi models")
    if arm["harness"] == "opencode" and arm.get("search_provider") != "tinyfish":
        # Only the keyless vendor-hosted provider is permitted: it needs no
        # account, key, or billing (ADR 0002). A keyed provider would reintroduce
        # the organizational dependency the OpenCode arm must not have.
        details.update(status="unavailable",
                       reason="OpenCode arm must pin the keyless tinyfish search provider")
    return details


def prepare_workspace(repos: dict[str, dict], task: dict, destination: Path) -> dict[str, str]:
    destination.mkdir(parents=True, exist_ok=False)
    commits: dict[str, str] = {}
    for name in task["repos"]:
        info = repos[name]
        source = Path(info["path"])
        target = destination / name
        target.mkdir(parents=True)
        proc = subprocess.Popen(["git", "-C", str(source), "archive", "--format=tar", info["commit"]],
                                stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        assert proc.stdout is not None
        links: list[tuple[Path, str]] = []
        with tarfile.open(fileobj=proc.stdout, mode="r|") as tar:
            for member in tar:
                member_path = (target / member.name).resolve()
                if not member_path.is_relative_to(target.resolve()):
                    proc.kill()
                    raise ValueError("Unsafe path in git archive")
                if member.issym():
                    if Path(member.linkname).is_absolute() or not (member_path.parent / member.linkname).resolve().is_relative_to(target.resolve()):
                        proc.kill()
                        raise ValueError("Unsafe symlink in git archive")
                    links.append((member_path, member.linkname))
                    continue
                if member.islnk():
                    proc.kill()
                    raise ValueError("Unsupported hard link in git archive")
                tar.extract(member, target, filter="data")
        stderr = proc.stderr.read().decode(errors="replace") if proc.stderr else ""
        if proc.wait() != 0:
            raise RuntimeError(f"git archive failed: {stderr[:500]}")
        proc.stdout.close()
        if proc.stderr:
            proc.stderr.close()
        for link_path, link_target in links:
            link_path.symlink_to(link_target)
        commits[name] = info["commit"]
    for path in destination.rglob("*"):
        if path.is_file():
            path.chmod(0o444)
        elif path.is_dir():
            path.chmod(0o555)
    destination.chmod(0o555)
    return commits


def tree_digest(root: Path) -> str:
    digest = hashlib.sha256()
    for path in sorted(root.rglob("*")):
        digest.update(str(path.relative_to(root)).encode())
        if path.is_file():
            digest.update(path.read_bytes())
    return digest.hexdigest()


def capture(command: list[str], cwd: Path, env: dict[str, str], timeout: int,
            events_path: Path) -> dict:
    """Capture stdout/stderr as received with monotonic offsets and no shell."""
    started_at = utc_now()
    start = time.monotonic()
    events: list[dict] = []
    q: queue.Queue[tuple[str, str | None]] = queue.Queue()
    proc = subprocess.Popen(command, cwd=cwd, env=env, stdout=subprocess.PIPE,
                            stderr=subprocess.PIPE, text=True, bufsize=1)

    def pump(stream: Any, channel: str) -> None:
        for line in stream:
            q.put((channel, line.rstrip("\n")))
        q.put((channel, None))

    assert proc.stdout and proc.stderr
    for channel, stream in (("stdout", proc.stdout), ("stderr", proc.stderr)):
        threading.Thread(target=pump, args=(stream, channel), daemon=True).start()
    ended = 0
    timed_out = False
    events_path.parent.mkdir(parents=True, exist_ok=True)
    with events_path.open("w") as output:
        while ended < 2:
            remaining = timeout - (time.monotonic() - start)
            if remaining <= 0 and proc.poll() is None:
                proc.kill()
                timed_out = True
            try:
                channel, line = q.get(timeout=0.2)
            except queue.Empty:
                continue
            if line is None:
                ended += 1
                continue
            try:
                data: Any = json.loads(line)
            except json.JSONDecodeError:
                data = {"raw_text": line}
            entry = {"index": len(events), "elapsed_seconds": round(time.monotonic() - start, 6),
                     "channel": channel, "data": data}
            events.append(entry)
            output.write(json.dumps(entry, ensure_ascii=False) + "\n")
            output.flush()
    exit_code = proc.wait()
    return {"events": events, "exit_code": exit_code, "timed_out": timed_out,
            "elapsed_seconds": round(time.monotonic() - start, 6), "started_at": started_at}


def run_one(arm: dict, task: dict, manifest: dict, evaluation_id: str,
            timeout: int | None = None) -> dict:
    run_dir = RESULTS / evaluation_id / "runs" / task["id"] / arm["id"]
    if run_dir.exists():
        raise ValueError(f"Run already exists: {run_dir}; use a new evaluation ID")
    run_dir.mkdir(parents=True)
    status = manifest["preflight"][arm["id"]]["status"]
    if status == "unavailable":
        metrics = {"task_id": task["id"], "arm_id": arm["id"], "status": "unavailable",
                   "reason": manifest["preflight"][arm["id"]]["reason"],
                   "started_at": utc_now(), "elapsed_seconds": 0, "answer": "",
                   "usage": {"classification": "unavailable", "source": None, "raw": None},
                   "first_visible_seconds": None, "first_substantive_seconds": None}
        (run_dir / "events.jsonl").write_text("")
        (run_dir / "answer.md").write_text("")
        atomic_json(run_dir / "metrics.json", metrics)
        return metrics
    if status != "ready":
        raise ValueError(f"Arm {arm['id']} has not passed live preflight")
    with tempfile.TemporaryDirectory(prefix="agent-eval-") as temporary:
        workspace = Path(temporary) / "workspace"
        prepare_workspace(manifest["repos"], {"repos": task_repo_names(task, manifest)}, workspace)
        before = tree_digest(workspace)
        env = adapters.environment(arm, workspace)
        session = None
        all_events: list[dict] = []
        phase_results: list[dict] = []
        asked = False
        answer = ""
        policy = read_config("run-policy")
        prompts = [task["prompt"], policy["continuation_response"]]
        for phase, prompt in enumerate(prompts):
            if phase and not asked:
                break
            event_path = run_dir / f"phase-{phase}.jsonl"
            cmd = adapters.command(arm, prompt, workspace, run_dir, session)
            if arm["harness"] == "copilot" and phase == 0:
                import uuid
                cmd[cmd.index("--session-id") + 1] = str(uuid.uuid4())
            result = capture(cmd, workspace, env, timeout or policy["timeout_seconds"], event_path)
            phase_results.append({key: value for key, value in result.items() if key != "events"})
            offset = sum(item["elapsed_seconds"] for item in phase_results[:-1])
            for entry in result["events"]:
                entry["index"] = len(all_events)
                entry["elapsed_seconds"] += offset
                entry["phase"] = phase
                all_events.append(entry)
            answer = adapters.final_answer(arm["harness"], result["events"])
            if phase == 0:
                asked = adapters.asked_question(result["events"], answer)
                session = adapters.session_id(arm["harness"], result["events"])
                if arm["harness"] == "copilot":
                    session = cmd[cmd.index("--session-id") + 1]
                if arm["harness"] == "pi":
                    session = str(run_dir / "pi-session.jsonl")
            if result["exit_code"] != 0 or result["timed_out"]:
                break
            if phase == 0 and asked and not session:
                break
        with (run_dir / "events.jsonl").open("w") as f:
            for entry in all_events:
                f.write(json.dumps(entry, ensure_ascii=False) + "\n")
        after = tree_digest(workspace)
        if before != after:
            status = "failed"
            reason = "Repository snapshot was modified"
        elif phase_results[-1]["timed_out"]:
            status, reason = "timeout", "Harness exceeded timeout"
        elif phase_results[-1]["exit_code"] != 0:
            status, reason = "failed", f"Harness exited {phase_results[-1]['exit_code']}"
        elif asked and not session:
            status, reason = "failed", "Clarification asked but session continuation was unavailable"
        elif not answer:
            status, reason = "failed", "No final answer parsed from events"
        else:
            status, reason = "completed", None
        first_visible = next((entry["elapsed_seconds"] for entry in all_events
                              if entry["channel"] == "stdout" and
                              adapters.event_text(arm["harness"], entry["data"])), None)
        usage = adapters.usage(arm["harness"], all_events, run_dir)
        (run_dir / "answer.md").write_text(answer + ("\n" if answer else ""))
        metrics = {"task_id": task["id"], "arm_id": arm["id"], "status": status,
                   "reason": reason, "started_at": phase_results[0]["started_at"],
                   "elapsed_seconds": sum(x["elapsed_seconds"] for x in phase_results),
                   "answer": answer, "usage": usage, "asked_clarification": asked,
                   "continuations": len(phase_results) - 1, "first_visible_seconds": first_visible,
                   "first_substantive_seconds": None, "snapshot_digest_before": before,
                   "snapshot_digest_after": after, "phases": phase_results,
                   "tool_activity": adapters.tool_activity(all_events)}
        atomic_json(run_dir / "metrics.json", metrics)
        return metrics


def randomized_slots(tasks: list[dict], arms: list[dict], seed: int) -> list[tuple[dict, dict]]:
    rng = random.Random(seed)
    result: list[tuple[dict, dict]] = []
    for task in tasks:
        order = list(arms)
        rng.shuffle(order)
        result.extend((task, arm) for arm in order)
    return result

"""CLI command construction and conservative event decoding.

Flags are deliberately explicit. A vendor upgrade must pass live preflight before
the runner will use it for an evaluation.
"""
from __future__ import annotations

import json
import os
import shutil
from pathlib import Path


def pi_binary_env() -> dict[str, str]:
    env = os.environ.copy()
    node = shutil.which("node")
    if node:
        try:
            import subprocess
            version = subprocess.check_output([node, "--version"], text=True, timeout=3).strip()
            if int(version.lstrip("v").split(".")[0]) >= 24:
                return env
        except (ValueError, OSError, subprocess.SubprocessError):
            pass
    nvm = Path.home() / ".nvm/versions/node"
    candidates = sorted(nvm.glob("v24.*/bin"), reverse=True)
    if candidates:
        env["PATH"] = str(candidates[0]) + os.pathsep + env.get("PATH", "")
    return env


def environment(arm: dict, workspace: Path) -> dict[str, str]:
    env = pi_binary_env() if arm["harness"] == "pi" else os.environ.copy()
    if arm["harness"] == "opencode":
        # OpenCode v2's server process reads OPENCODE_CONFIG_CONTENT, keeping this
        # per-process and independent from the user's global config. Permissions
        # are deny-by-default (last matching rule wins; unmatched actions "ask",
        # which headless runs auto-reject). tinyfish is the vendor-hosted keyless
        # search provider: no account, key, or billing.
        env["OPENCODE_CONFIG_CONTENT"] = json.dumps({
            "permissions": [
                {"action": "*", "resource": "*", "effect": "deny"},
                {"action": "read", "resource": "*", "effect": "allow"},
                {"action": "glob", "resource": "*", "effect": "allow"},
                {"action": "grep", "resource": "*", "effect": "allow"},
                {"action": "websearch", "resource": "*", "effect": "allow"},
                {"action": "webfetch", "resource": "*", "effect": "allow"},
                {"action": "question", "resource": "*", "effect": "allow"},
            ],
            "websearch": {"provider": arm.get("search_provider", "tinyfish")},
        })
    env["AGENT_EVAL_WORKSPACE"] = str(workspace)
    return env


def command(arm: dict, prompt: str, workspace: Path, run_dir: Path,
            session: str | None = None) -> list[str]:
    harness = arm["harness"]
    binary = arm["binary"]
    model = arm["model"]
    effort = arm["reasoning"]
    if harness == "pi":
        # Explicit --provider/--model instead of "provider/model" in --model: a
        # default provider profile (~/.config/pi/provider-profile) otherwise
        # hijacks unresolvable combined references.
        provider, _, model_id = model.partition("/")
        cmd = [binary, "--print", "--mode", "json",
               "--provider", provider, "--model", model_id,
               "--thinking", effort, "--tools", "read,grep,find,ls,web_search,web_fetch",
               "--no-context-files", "--no-skills", "--no-approve",
               "--session", str(run_dir / "pi-session.jsonl")]
        return cmd + ["--", prompt]
    if harness == "copilot":
        cmd = [binary, "--prompt", prompt, "--model", model,
               "--reasoning-effort", effort, "--output-format", "json",
               "--allow-all-tools", "--allow-all-urls", "--no-custom-instructions",
               "--no-auto-update", "--usage-output-file", str(run_dir / "copilot-usage.json"),
               "-C", str(workspace), "--session-id", session or run_dir.name,
               "--available-tools=web_search,web_fetch,view,grep,glob,ask_user"]
        return cmd
    if harness == "opencode":
        # --standalone forces a private server that inherits this process's
        # OPENCODE_CONFIG_CONTENT instead of attaching to a user's background
        # service with unrelated config. v2 pins the effort variant to the model
        # string as provider/model#variant.
        cmd = [binary, "run", "--standalone", "--format", "json",
               "--model", f"{model}#{effort}"]
        if session:
            cmd += ["--session", session]
        return cmd + [prompt]
    if harness == "claude":
        cmd = [binary, "-p", prompt, "--model", model, "--effort", effort,
               "--output-format", "stream-json", "--verbose", "--restricted",
               "--tools", "Read,Glob,Grep,WebSearch,WebFetch,AskUserQuestion",
               "--allowedTools", "Read,Glob,Grep,WebSearch,WebFetch,AskUserQuestion",
               "--permission-mode", "dontAsk",
               "--disallowedTools", "mcp__*"]
        if session:
            cmd += ["--resume", session]
        return cmd
    if harness == "antigravity":
        cmd = [binary, "-p", prompt, "--model", model, "--effort", effort,
               "--output-format", "stream-json", "--sandbox"]
        if session:
            cmd += ["--conversation", session]
        return cmd
    raise ValueError(f"Unknown harness: {harness}")


def event_text(harness: str, obj: object) -> str:
    if not isinstance(obj, dict):
        return ""
    if harness == "pi":
        if obj.get("type") == "message_update":
            delta = obj.get("assistantMessageEvent", {})
            return delta.get("delta", "") if isinstance(delta, dict) and delta.get("type") == "text_delta" else ""
        if obj.get("type") == "message_end":
            message = obj.get("message", {})
            return _content_text(message.get("content")) if message.get("role") == "assistant" else ""
    if harness == "copilot":
        data = obj.get("data", {})
        if obj.get("type") in ("assistant.message_delta", "assistant.message"):
            return data.get("deltaContent") or data.get("content") or ""
    if harness == "opencode":
        part = obj.get("part", {})
        if obj.get("type") == "text":
            return part.get("text", "") if isinstance(part, dict) else ""
    if harness == "claude":
        if obj.get("type") == "assistant":
            return _content_text(obj.get("message", {}).get("content"))
        if obj.get("type") == "stream_event":
            delta = obj.get("event", {}).get("delta", {})
            return delta.get("text", "") if isinstance(delta, dict) else ""
        if obj.get("type") == "result":
            return obj.get("result", "") if isinstance(obj.get("result"), str) else ""
    if harness == "antigravity":
        if obj.get("event") == "step_update":
            return obj.get("step_update", {}).get("text_delta", "")
        if obj.get("event") == "result":
            return obj.get("result", {}).get("response", "")
    return ""


def _content_text(content: object) -> str:
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        return "".join(str(x.get("text", "")) for x in content if isinstance(x, dict) and x.get("type") == "text")
    return ""


def final_answer(harness: str, events: list[dict]) -> str:
    # Prefer a terminal answer; fall back to the last complete assistant event,
    # then assembled deltas. Never use tool output as an answer.
    completed: list[str] = []
    deltas: list[str] = []
    for entry in events:
        obj = entry.get("data")
        if not isinstance(obj, dict):
            continue
        kind = str(obj.get("type", obj.get("event", "")))
        value = event_text(harness, obj)
        if not value:
            continue
        if kind in ("result", "message_end", "assistant.message", "assistant", "text"):
            completed.append(value)
        else:
            deltas.append(value)
    return (completed[-1] if completed else "".join(deltas)).strip()


def session_id(harness: str, events: list[dict]) -> str | None:
    keys = {"pi": ("sessionId",), "copilot": ("sessionId", "session_id"),
            "opencode": ("sessionID", "sessionId"), "claude": ("session_id",),
            "antigravity": ("conversation_id",)}[harness]
    for entry in events:
        obj = entry.get("data")
        if not isinstance(obj, dict):
            continue
        for container in (obj, obj.get("data", {}), obj.get("result", {})):
            if isinstance(container, dict):
                for key in keys:
                    if isinstance(container.get(key), str) and container[key]:
                        return container[key]
    return None


def tool_names(events: list[dict]) -> list[str]:
    names: list[str] = []
    for entry in events:
        obj = entry.get("data")
        if not isinstance(obj, dict):
            continue
        event_type = str(obj.get("type", obj.get("event", ""))).lower()
        if any(term in event_type for term in ("tool_execution_start", "tool.execution_start",
                                               "tool_call", "tool_use", "function", "question")):
            for container in (obj, obj.get("data"), obj.get("part"), obj.get("tool_call"),
                              obj.get("toolCall"), obj.get("step_update")):
                if isinstance(container, dict):
                    for key in ("toolName", "tool_name", "tool", "name"):
                        value = container.get(key)
                        if isinstance(value, str):
                            names.append(value)
        if event_type == "step_update":
            step = obj.get("step_update", {})
            if isinstance(step, dict) and step.get("step_type") == "tool" and step.get("state") == "DONE":
                value = step.get("tool_name")
                if isinstance(value, str):
                    names.append(value)
        # Pi and Claude include tool calls as assistant content blocks.
        message = obj.get("message")
        if isinstance(message, dict) and message.get("role") == "assistant":
            for block in message.get("content", []):
                if isinstance(block, dict) and block.get("type") in ("toolCall", "tool_use"):
                    value = block.get("name")
                    if isinstance(value, str):
                        names.append(value)
    return list(dict.fromkeys(names))


def completed_claude_tool_names(events: list[dict]) -> list[str]:
    """Only count Claude tools with a successful tool_result, not permission requests."""
    requested: dict[str, str] = {}
    completed: list[str] = []
    for entry in events:
        obj = entry.get("data")
        if not isinstance(obj, dict):
            continue
        message = obj.get("message", {})
        if not isinstance(message, dict):
            continue
        blocks = message.get("content", [])
        if not isinstance(blocks, list):
            continue
        if obj.get("type") == "assistant":
            for block in blocks:
                if isinstance(block, dict) and block.get("type") == "tool_use":
                    if isinstance(block.get("id"), str) and isinstance(block.get("name"), str):
                        requested[block["id"]] = block["name"]
        elif obj.get("type") == "user":
            for block in blocks:
                if isinstance(block, dict) and block.get("type") == "tool_result" and not block.get("is_error"):
                    name = requested.get(block.get("tool_use_id"))
                    if name:
                        completed.append(name)
    return completed


def tool_activity(events: list[dict]) -> dict[str, int]:
    counts = {"search_calls": 0, "fetch_calls": 0, "other_tool_calls": 0}
    for entry in events:
        obj = entry.get("data")
        if not isinstance(obj, dict):
            continue
        kind = str(obj.get("type", obj.get("event", "")))
        name = None
        if kind in ("tool_execution_start", "tool.execution_start", "tool", "tool_use"):
            container = obj.get("data") or obj.get("part") or obj
            if isinstance(container, dict):
                name = container.get("toolName") or container.get("tool") or container.get("name")
        elif kind == "step_update":
            step = obj.get("step_update", {})
            if isinstance(step, dict) and step.get("step_type") == "tool" and step.get("state") == "DONE":
                name = step.get("tool_name")
        if not isinstance(name, str):
            continue
        if any(term in name.lower() for term in ("web_search", "websearch", "search_web")):
            counts["search_calls"] += 1
        elif any(term in name.lower() for term in ("fetch", "browse", "webpage", "read_url_content")):
            counts["fetch_calls"] += 1
        else:
            counts["other_tool_calls"] += 1
    for name in completed_claude_tool_names(events):
        if name == "WebSearch":
            counts["search_calls"] += 1
        elif name == "WebFetch":
            counts["fetch_calls"] += 1
        else:
            counts["other_tool_calls"] += 1
    return counts


def asked_question(events: list[dict], answer: str) -> bool:
    if any(any(term in name.lower() for term in ("question", "ask_user", "askuser")) for name in tool_names(events)):
        return True
    # Only a question-only final response is treated as a request to continue.
    lines = [line.strip() for line in answer.splitlines() if line.strip()]
    return bool(lines) and len(lines) <= 3 and lines[-1].endswith("?") and not any("." in line for line in lines)


def usage(harness: str, events: list[dict], run_dir: Path) -> dict:
    if harness == "copilot" and (run_dir / "copilot-usage.json").exists():
        try:
            raw = json.loads((run_dir / "copilot-usage.json").read_text())
            return {"classification": "measured", "source": "copilot --usage-output-file", "raw": raw}
        except (OSError, json.JSONDecodeError):
            pass
    if harness == "opencode":
        # v2 reports cost and tokens on each step_finish part rather than a
        # usage object; the last one summarizes the run.
        for entry in reversed(events):
            obj = entry.get("data")
            if isinstance(obj, dict) and obj.get("type") == "step_finish":
                part = obj.get("part", {})
                if isinstance(part, dict) and ("tokens" in part or "cost" in part):
                    return {"classification": "measured", "source": "opencode step_finish",
                            "raw": {key: part[key] for key in ("tokens", "cost") if key in part}}
    for entry in reversed(events):
        obj = entry.get("data")
        if not isinstance(obj, dict):
            continue
        for container in (obj, obj.get("result", {}), obj.get("message", {})):
            if isinstance(container, dict) and isinstance(container.get("usage"), dict):
                return {"classification": "measured", "source": "provider event", "raw": container["usage"]}
    return {"classification": "unavailable", "source": None, "raw": None}

