def test_run_uses_injected_workspace_lifecycle_without_changing_metrics(self):
    arm = {"id": "test-arm", "harness": "opencode"}
    task = {"id": "TEST", "repos": ["sample"], "prompt": "Answer"}
    manifest = {"preflight": {"test-arm": {"status": "ready"}}, "repos": {"sample": {}}}
    conversation = {"events": [], "phases": [{"started_at": "start", "elapsed_seconds": 1.0,
                                                 "exit_code": 0, "timed_out": False}],
                    "asked_clarification": False, "answer": "answer", "session": None}
    with tempfile.TemporaryDirectory() as temp:
        root = Path(temp)
        workspace = root / "provided-workspace"
        workspace.mkdir()
        calls = {"entered": False, "exited": False}

        @contextmanager
        def provider(repos, workspace_task):
            calls.update(entered=True, repos=repos, task=workspace_task)
            try:
                yield workspace
            finally:
                calls["exited"] = True

        with patch("src.agent_eval.core.RESULTS", root / "results"), \\
                patch("src.agent_eval.core.adapters.environment", return_value={}), \\
                patch("src.agent_eval.core.capture_conversation", return_value=conversation):
            metrics = run_one(arm, task, manifest, "evaluation", workspace_provider=provider)

        self.assertTrue(calls["entered"] and calls["exited"])
        self.assertEqual(calls["repos"], manifest["repos"])
        self.assertEqual(calls["task"], {"repos": ["sample"]})
        self.assertEqual(metrics["status"], "completed")
        self.assertEqual(metrics["answer"], "answer")
        self.assertEqual(metrics["continuations"], 0)
        self.assertEqual(metrics["usage"]["classification"], "unavailable")

